        # Spawn an interactive bash inside a fresh pty.
        # -u forces unbuffered stdio in bash so output comes out promptly.
        self.child = pexpect.spawn(
            "/usr/bin/env",
            ["-u", "bash", "-i"],
            dimensions=(height, width),
            encoding="utf-8",
            codec_errors="replace",
            timeout=timeout,
            echo=False,
            env={**os.environ, "TERM": os.environ.get("TERM", "xterm")},
        )
        # Give bash a moment to start up and print its first prompt.
        try:
