        except pexpect.EOF:
            pass
        # Drain whatever initial banner/prompt was produced.
        try:
            self.child.read_nonblocking(size=1_000_000, timeout=0.3)
        except (pexpect.TIMEOUT, pexpect.EOF):
            pass

