    # Core interface                                                      #
    # ------------------------------------------------------------------ #
    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        """Send raw keystrokes to the terminal.

        ``keystrokes`` is sent verbatim as bytes (UTF-8 encoded), so escape
        sequences like ``\x03`` (Ctrl+C) or ``\x1b`` (Escape) work as
        modifier/control keys.  After sending, if ``wait_sec`` > 0, the
        terminal blocks for up to that many seconds waiting for output.
        """
