            self.child.send(keystrokes)
        if wait_sec and wait_sec > 0:
            self._drain(timeout=wait_sec)

    # ------------------------------------------------------------------ #
    # Convenience helpers (not part of the abstract interface)             #
    # ------------------------------------------------------------------ #
    def send_line(self, line: str, wait_sec: float = 0.0) -> None:
        """Convenience wrapper: send a line followed by Enter."""
        self.send_keystrokes(line + "\n", wait_sec=wait_sec)

