        """Read up to ``timeout`` seconds worth of pending output."""
        return self._drain(timeout=timeout)

    def recv_until(self, pattern, timeout: float = 5.0) -> str:
        """Read until ``pattern`` is seen in the output, or timeout elapses."""
        try:
            self.child.expect(pattern, timeout=timeout)
            return self.child.before + self.child.after
        except (pexpect.TIMEOUT, pexpect.EOF):
            return self.child.before

