        return bool(self.child) and self.child.isalive()

    def close(self) -> None:
        """Terminate the shell and free the pty."""
        try:
            if self.child.isalive():
                # Ask bash nicely to exit, then hard-close.
                try:
                    self.child.send("exit\n")
                except Exception:
                    pass
